NAME = 'ACV: A Conservative Version'
BOOK = 'II Peter'

CHAPTERS = {
    1: {
        1: 'Simon Peter, hlapec in apostol Jezusa Kristusa, njim, ki so zadobili z nami enako dragoceno vero po pravičnosti Boga našega in Zveličarja Jezusa Kristusa:',
        2: 'Milost vam in mir naj se pomnoži v spoznanju Boga in Jezusa Gospoda našega;',
        3: 'kakor nam je Božja moč njegova podarila vse, kar služi v življenje in pobožnost, po spoznanju njega, ki nas je poklical po lastni slavi in kreposti,',
        4: 'po čemer nam je podaril dragocene in največje obljube, da postanete po njih deležniki Božje narave, ko ste ubežali pogubi, ki jo na svetu provzroča poželenje.',
        5: 'Prav zato si prizadevajte z vso gorečnostjo ter kažite v veri svoji krepost, v kreposti pa spoznanje, v spoznanju pa zmernost,',
        6: 'v zmernosti pa stanovitnost, v stanovitnosti pa pobožnost,',
        7: 'v pobožnosti pa bratoljubje, v bratoljubju pa ljubezen do vseh.',
        8: 'Kajti če so te čednosti v vas in se množe, napravljajo, da niste nedelavni in nerodovitni v spoznanju Gospoda našega Jezusa Kristusa.',
        9: 'Kdor namreč nima teh, je slep, kratkoviden, ker je pozabil, da je bil očiščen starih grehov svojih.',
        10: 'Zato se, bratje, tem bolj trudite, da utrdite poklic svoj in izvoljenje; kajti če tako delate, ne spotaknete se nikdar.',
        11: 'Tako namreč vam bo dan zmagoslaven vhod v večno kraljestvo Gospoda našega in Zveličarja Jezusa Kristusa.',
        12: 'Zato ne bom vnemar pustil, vedno vas spominjati tega, dasi to veste in ste utrjeni v dani vam resnici.',
        13: 'Menim pa, da je prav, dokler sem v tej koči, da vas izpodbujam, kličoč vam to v spomin,',
        14: 'ker vem, da moram skoraj odložiti kočo svojo, kakor mi je tudi Gospod naš Jezus Kristus naznanil.',
        15: 'Potrudim se pa, da se morete tudi vsak čas po mojem odhodu spominjati tega.',
        16: 'Kajti nismo se držali izmišljenih basni, ko smo vam oznanili Gospoda našega Jezusa Kristusa moč in prihod, marveč sami smo videli in bili priče njegovega veličastva.',
        17: 'Prejel je namreč od Boga Očeta čast in slavo, ko mu je prišel tak glas od veličastne slave: Ta je Sin moj ljubljeni, ki je po moji volji;',
        18: 'in ta glas smo mi slišali, da je prišel z neba, ko smo bili ž njim na sveti gori.',
        19: 'In imamo besedo proroško tem trdnejšo; in prav delate, da pazite nanjo kakor na svetilnico, ki sveti v temnem kraju, dokler ne prisije dan in danica vzide v srcih vaših;',
        20: 'to najprej spoznavajoč, da se nobeno prorokovanje pisma ne godi po lastnem razlaganju.',
        21: 'Zakaj prorokovanje ni nikdar prišlo po volji človeški, temuč od Boga so govorili ljudje, kakor jih je vodil sveti Duh.',
    },
    2: {
        1: 'Nastopili so pa tudi lažnivi proroki v ljudstvu, kakor bodo tudi med vami lažnivi učitelji, ki bodo vtihotapljali pogubne krive nauke in zatajevali celo Gospoda, ki jih je odkupil, in s tem si pripravljali naglo pogubo.',
        2: 'In mnogo jih bo hodilo za njih razuzdanostmi, zavoljo katerih se bo preklinjala pot resnice.',
        3: 'In v lakomnosti vas bodo izkoriščali z izmišljenimi besedami; katerim sodba že zdavnaj ne odlaša, in poguba njih ne dremlje.',
        4: 'Kajti Bog ni prizanesel angelom, ki so grešili, temuč jih je z verigami teme pahnil v brezno in jih dal hraniti za sodbo;',
        5: 'in prvemu svetu ni prizanesel, temuč je kot osmega ohranil Noeta, glasnika pravičnosti, ko je poslal potop čez svet brezbožnih;',
        6: 'in mesti Sodomo in Gomoro je obsodil v razpad ter ju upepelil, s čimer ju je za zgled postavil tistim, ki bodo brezbožno živeli;',
        7: 'in pravičnega Lota, trpečega od razuzdanega vedenja krivičnikov, je otel',
        8: '(kajti s pogledom in sluhom je ta pravičnik dan na dan mučil pravično dušo svojo ž njih nepostavnimi deli, prebivajoč med njimi).',
        9: 'Gospod ve pobožne rešiti iz izkušnjave, krivične pa za dan sodbe hraniti v kaznovanje,',
        10: 'najbolj pa nje, ki hodijo za mesom v poželenju oskrumbe in zaničujejo gospostvo. Predrzneži, svojevoljneži, ne boje se preklinjati veličanstev,',
        11: 'ko vendar angeli, po krepkosti in moči večji, ne izrekajo zoper nje pred Gospodom preklinjajoče sodbe.',
        12: 'Ti pa kakor nespametne živali, po naravi rojene za lov in klanje, ker preklinjajo, česar ne poznajo, se bodo pogubili v pogubi svoji,',
        13: 'prejemši krivice plačilo. Njim se veselje zdi požrešnost po dnevi, nesnage so in grdobe, razkošno žive v sleparstvih svojih in se goste z vami,',
        14: 'oči imajo polne prešeštvovanja in nikdar ne sitih greha, vabijo duše neutrjene, imajo srce vajeno v lakomnosti in so prokletstva otroci;',
        15: 'zapustili so ravno pot ter tavali in hodili po poti Balaama, sina Bosorjevega, ki je ljubil krivice plačilo,',
        16: 'a prejel posvarilo za lastno nepostavnost: brezglasno vprežno živinče je izpregovorilo s človeškim glasom ter zabranilo prorokovo nespamet.',
        17: 'Ti so studenci brez vode in megle, ki jih goni vihar, ki jim je shranjen mrak večne teme.',
        18: 'Kajti prešerno in ničemurno govoreč, vabijo s poželenjem mesa, z razuzdanostmi one, ki so komaj ubežali njim, ki hodijo v zmotnjavi,',
        19: 'obetajoč jim svobodo, ko so sami sužnji pogube; zakaj od kogar je kdo premagan, tistemu je postal suženj.',
        20: 'Če se namreč taki, ki so ubežali oskrumbam sveta po spoznanju Gospoda in Zveličarja Jezusa Kristusa, zopet zapleto vanje in so premagani, je postalo njih poslednje hujše od prvega.',
        21: 'Kajti bolje bi jim bilo, da bi ne bili spoznali pota pravičnosti, nego pa da so se po spoznanju obrnili zopet od dane jim svete zapovedi.',
        22: 'Prigodilo se jim je pa po resničnem pregovoru: Pes se vrne k temu, kar je izbljuval, in svinja omita v lužo blatno.',
    },
    3: {
        1: 'Tu vam, ljubljeni, pišem že drugi list in v obeh zbujam z opominom vaše čisto mišljenje,',
        2: 'da se spominjate prej govorjenih besed svetih prorokov in zapovedi Gospoda in Zveličarja, ki ste jo prejeli od svojih apostolov,',
        3: 'to najprej vedoč, da pridejo v zadnjih dneh posmehovalci z zasmehovanjem, ki žive po lastnih svojih poželenjih',
        4: 'in govoré: Kje je obljuba prihoda njegovega? Saj odkar so zaspali očetje, je vse, kakor je bilo od začetka stvaritve.',
        5: 'Hotoma namreč ne vedo tega, da so bila od nekdaj nebesa in zemlja, ki je postala iz vode in z vodo po besedi Božji,',
        6: 'po kateri je tedanji svet poginil z vodo potopljen;',
        7: 'sedanja nebesa pa in zemlja so bila po isti besedi shranjena za ogenj in se vzdržujejo za dan sodbe in pogube brezbožnih ljudi.',
        8: 'To eno pa vam ne bodi skrito, ljubljeni, da je en dan pred Gospodom kakor tisoč let in tisoč let kakor en dan.',
        9: 'Gospod ne odlaša obljube, kar imajo nekateri za odlašanje; temuč potrpežljiv je z vami, ker noče, da se kdo pogubi, ampak da vsi pridejo do izpokorjenja.',
        10: 'Pride pa dan Gospodov kakor tat, v katerem preidejo nebesa z velikim ropotom in prvine razpadejo v požaru in zemlja in vsa dela na njej zgore.',
        11: 'Ker ima torej vse to razpasti, koliki morate biti vi v svetem življenju in pobožnosti,',
        12: 'ki čakate in pospešujete prihod dneva Božjega, spričo katerega razpadejo nebesa v ognju in se prvine goreč raztope.',
        13: 'Novih pa nebes in nove zemlje pričakujemo po obljubi njegovi, v katerih prebiva pravičnost.',
        14: 'Zato, ljubljeni, trudite se, tega čakajoč, da se pokažete brez madeža in brez hibe pred njim v miru.',
        15: 'In potrpežljivost Gospoda našega imejte za zveličanje; kakor vam je tudi ljubljeni brat naš Pavel pisal po dani mu modrosti,',
        16: 'kakor i v vseh listih svojih, govoreč v njih o teh rečeh; ki je v njih nekaj težko umljivega, kar nevedni in neutrjeni zavijajo, kakor tudi druga pisma, v lastno pogubo svojo.',
        17: 'Vi torej, ljubljeni, ki to naprej veste, pazite, da vas pregrešnih zmota ne potegne za seboj in ne padete iz lastnega trdnega stanja,',
        18: 'temuč rastite v milosti in spoznanju Gospoda našega in Zveličarja Jezusa Kristusa. Njemu slava i sedaj i na dan večnosti!',
    },
}
